@pragma('vm:entry-point')
double mazeCellOpenPassageRatio(int cell) {
  int flags = cell & 0xF;
  int walls = 0;
  for (int i = 0; i < 4; i++) {
    walls += flags & 1;
    flags >>= 1;
  }
  return (4 - walls) / 4.0;
}

