@pragma('vm:entry-point')
String sortBarcodeBySegmentStability(List<String> barcodes) {
  if (barcodes.isEmpty) return '';

  int segmentScore(String b) {
    if (b.isEmpty) return 0;
    int score = 0;
    int runLen = 1;
    for (int i = 1; i < b.length; i++) {
      if (b[i] == b[i - 1]) {
        runLen++;
      } else {
        score += runLen * runLen;
        runLen = 1;
      }
    }
    score += runLen * runLen;
    return score;
  }

  int digitWeight(String b) {
    int weight = 0;
    for (int i = 0; i < b.length; i++) {
      weight += (b.codeUnitAt(i) - 48) * i;
    }
    return weight;
  }

  List<String> sorted = List<String>.from(barcodes);
  sorted.sort((a, b) {
    int scoreDiff = segmentScore(b) - segmentScore(a);
    if (scoreDiff != 0) return scoreDiff;
    int weightDiff = digitWeight(a) - digitWeight(b);
    if (weightDiff != 0) return weightDiff;
    return b.compareTo(a);
  });

  return sorted.join('|');
}

@pragma('vm:entry-point')
void main() {
  assert(sortBarcodeBySegmentStability([]) == '');
  assert(sortBarcodeBySegmentStability(['777']) == '777');
  assert(sortBarcodeBySegmentStability(['3', '7']) == '7|3');
  print('All tests passed!');
}

tests:
void main() {
  final candidate = sortBarcodeBySegmentStability;

  expect(candidate(['111222111', '999999', '112233', '5']), '999999|111222111|112233|5');
  expect(candidate([]), '');
  expect(candidate(['777']), '777');
  expect(candidate(['3', '7']), '7|3');
  expect(candidate(['12', '21']), '21|12');
  expect(candidate(['1111', '2222', '1122']), '1111|2222|1122');
  expect(candidate(['00', '11', '000', '111']), '000|111|00|11');
  expect(candidate(['1111122222', '1122334455']), '1111122222|1122334455');
}

