@pragma('vm:entry-point')
bool ingredientsOverlapAfterScale(int x1, int y1, int x2, int y2, int x3, int y3, int x4, int y4, int margin) {
  // Expand the first ingredient rectangle by margin in all directions
  int sx1 = x1 - margin;
  int sy1 = y1 - margin;
  int sx2 = x2 + margin;
  int sy2 = y2 + margin;
  // Two axis-aligned rectangles overlap iff they overlap in both dimensions
  // (strict overlap, touching edges is NOT overlapping)
  return sx1 < x4 && x3 < sx2 && sy1 < y4 && y3 < sy2;
}

