@pragma('vm:entry-point')
bool isTelemetryAnomalyTolerant(List<int> samples, int maxAnomalies) {
  if (samples.isEmpty) return true;

  bool check(int idx, int anomalyCount) {
    if (idx >= samples.length) return true;
    if (anomalyCount > maxAnomalies) return false;

    int leftIdx = 2 * idx + 1;
    int rightIdx = 2 * idx + 2;
    bool hasLeft = leftIdx < samples.length;
    bool hasRight = rightIdx < samples.length;

    if (!hasLeft && !hasRight) return true;

    int v = samples[idx];
    bool valid = false;

    if (hasLeft && hasRight) {
      int a = samples[leftIdx];
      int b = samples[rightIdx];
      valid = (v == a + b) || (v == (a - b).abs());
    } else if (hasLeft) {
      valid = (v == samples[leftIdx]);
    } else {
      valid = (v == samples[rightIdx]);
    }

    int nextCount = valid ? anomalyCount : anomalyCount + 1;
    if (nextCount > maxAnomalies) return false;

    return (!hasLeft || check(leftIdx, nextCount)) &&
           (!hasRight || check(rightIdx, nextCount));
  }

  return check(0, 0);
}

@pragma('vm:entry-point')
void main() {
  assert(isTelemetryAnomalyTolerant([], 0) == true);
  assert(isTelemetryAnomalyTolerant([7], 0) == true);
  assert(isTelemetryAnomalyTolerant([5, 2, 3], 0) == true);
  print('All tests passed!');
}

tests:
void main() {
  final candidate = isTelemetryAnomalyTolerant;

  expect(candidate([], 0), true);
  expect(candidate([7], 0), true);
  expect(candidate([5, 2, 3], 0), true);
  expect(candidate([1, 3, 2], 0), true);
  expect(candidate([5, 3, 3], 0), false);
  expect(candidate([5, 3, 3], 1), true);
  expect(candidate([7, 3, 4, 1, 2, 2, 3], 0), false);
  expect(candidate([7, 3, 4, 1, 2, 2, 3], 1), true);
  expect(candidate([6, 3, 4, 1, 2, 2, 3], 1), false);
}

