@pragma('vm:entry-point')
int calculateUniqueMorseDuration(List<String> signals) {
  return signals
      .toSet()
      .where((s) => s.isNotEmpty && s.split('').every((c) => c == '.' || c == '-'))
      .fold(0, (sum, s) {
    int dots = s.split('').where((c) => c == '.').length;
    int dashes = s.length - dots;
    return sum + dots + (dashes * 3);
  });
}

@pragma('vm:entry-point')
void main() {
  assert(calculateUniqueMorseDuration(['.-', '.-']) == 4);
  assert(calculateUniqueMorseDuration(['...', '---', '']) == 12);
  assert(calculateUniqueMorseDuration(['.-a', '..']) == 2);
  print('All tests passed!');
}

tests:
void main() {
  final candidate = calculateUniqueMorseDuration;

  expect(candidate([]), 0);
  expect(candidate(['.', '-']), 4);
  expect(candidate(['..', '..']), 2);
  expect(candidate(['...', '---']), 12);
  expect(candidate(['.-', '.-a']), 4);
  expect(candidate(['...---...']), 15);
  expect(candidate(['', ' ']), 0);
  expect(candidate(['.-.-', '--..', 'abc', ' ']), 16);
  expect(candidate(['', 'a', '.-.', '..-']), 10);
}

