@pragma('vm:entry-point')
Set<int> primeSatellitePassMinutes(List<String> encodedStarts, int base, int windowLength, int cycleMinutes) {
  bool isPrime(int n) {
    if (n < 2) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;
    for (int d = 3; d * d <= n; d += 2) {
      if (n % d == 0) return false;
    }
    return true;
  }

  int digitOf(int code) {
    if (code >= 48 && code <= 57) return code - 48;
    if (code >= 65 && code <= 90) return code - 55;
    if (code >= 97 && code <= 122) return code - 87;
    return -1;
  }

  final Set<int> hits = <int>{};
  if (base < 2 || base > 36 || windowLength <= 0 || cycleMinutes <= 1) {
    return hits;
  }

  for (final String label in encodedStarts) {
    int start = 0;
    bool valid = label.isNotEmpty;
    for (int i = 0; i < label.length; i++) {
      final int digit = digitOf(label.codeUnitAt(i));
      if (digit < 0 || digit >= base) {
        valid = false;
        break;
      }
      start = (start * base + digit) % cycleMinutes;
    }
    if (!valid) continue;

    int minute = start;
    for (int offset = 0; offset < windowLength; offset++) {
      if (isPrime(minute)) hits.add(minute);
      minute++;
      if (minute == cycleMinutes) minute = 0;
    }
  }
  return hits;
}

