@pragma('vm:entry-point')
int countMorseLetterOccurrences(List<List<String>> grid) {
  if (grid.isEmpty) return 0;
  final rows = grid.length;
  final cols = grid[0].length;
  if (cols == 0) return 0;

  const morseCodes = {
    '.-', '-...', '-.-.', '-..', '.', '..-.', '--.', '....', '..',
    '.---', '-.-', '.-..', '--', '-.', '---', '.--.', '--.-', '.-.',
    '...', '-', '..-', '...-', '.--', '-..-', '-.--', '--..'
  };

  var count = 0;
  for (var i = 0; i < rows; i++) {
    for (var j = 0; j < cols; j++) {
      // horizontal sequences
      var maxHorizLen = 4;
      if (cols - j < maxHorizLen) maxHorizLen = cols - j;
      for (var len = 1; len <= maxHorizLen; len++) {
        var sb = StringBuffer();
        for (var k = 0; k < len; k++) {
          sb.write(grid[i][j + k]);
        }
        if (morseCodes.contains(sb.toString())) {
          count++;
        }
      }
      // vertical sequences
      var maxVertLen = 4;
      if (rows - i < maxVertLen) maxVertLen = rows - i;
      for (var len = 1; len <= maxVertLen; len++) {
        var sb = StringBuffer();
        for (var k = 0; k < len; k++) {
          sb.write(grid[i + k][j]);
        }
        if (morseCodes.contains(sb.toString())) {
          count++;
        }
      }
    }
  }
  return count;
}

