List<int> scaleRecipeIngredients(List<int> amounts, int factor) {
  List<int> stack = [];
  for (int amount in amounts) {
    stack.add(amount);
  }
  List<int> scaled = [];
  while (stack.isNotEmpty) {
    scaled.add(stack.removeLast() * factor);
