@pragma('vm:entry-point')
int kthStrongestInWifiBin(List<int> signals, List<int> binBoundaries, int binIndex, int k) {
  // Validate binBoundaries and binIndex
  if (binBoundaries.length < 2) return -1;
  if (binIndex < 0 || binIndex >= binBoundaries.length - 1) return -1;

  int binLow = binBoundaries[binIndex];
  int binHigh = binBoundaries[binIndex + 1] - 1; // upper bound exclusive in boundaries

  if (binLow > binHigh) return -1; // empty bin range

  // Count signals in the bin
  int countInBin = 0;
  for (int s in signals) {
    if (s >= binLow && s <= binHigh) countInBin++;
  }

  // Validate k
  if (k <= 0 || k > countInBin) return -1;

  // Binary search for kth largest signal in [binLow, binHigh]
  int low = binLow;
  int high = binHigh;
  while (low < high) {
    // Use upper mid to avoid infinite loop when low+1 == high
    int mid = low + ((high - low + 1) >> 1);
    int count = 0;
    for (int s in signals) {
      if (s >= mid && s <= binHigh) count++;
    }
    if (count >= k) {
      low = mid; // mid is candidate, search higher
    } else {
      high = mid - 1; // mid too high, search lower
    }
  }
  return low;
}

@pragma('vm:entry-point')
