double findFirstMoistureAtLeast(List<double> moistureGrid, double target) {
  int low = 0;
  int high = moistureGrid.length;
  while (low < high) {
    int mid = (low + high) >> 1;
    if (moistureGrid[mid] < target) {
      low = mid + 1;
    } else {
      high = mid;
    }
  }
  return (low < moistureGrid.length) ? moistureGrid[low] : -1.0;
}

