  assert(findFirstMoistureAtLeast([0.0, 0.5, 1.0], 0.5) == 0.5);
  assert(findFirstMoistureAtLeast([0.0, 0.5, 1.0], 0.75) == 1.0);
  assert(findFirstMoistureAtLeast([], 0.5) == -1.0);
