  assert(calculateUnionAreaOfDistricts([]) == 0);
  assert(calculateUnionAreaOfDistricts([[0,0,2,2]]) == 4);
  assert(calculateUnionAreaOfDistricts([[0,0,2,2], [3,0,5,2]]) == 8);
  print('All tests passed!');
}

