Map<String, int> calculateTotalHeatingTime(List<Map<String, Object>> schedule, int minTemperature) {
  final totals = <String, int>{};
  for (final node in schedule) {
    final type = node['type'] as String;
    if (type == 'interval') {
      final zone = node['zone'] as String;
      final start = node['start'] as int;
      final end = node['end'] as int;
      final temperature = node['temperature'] as int;
      if (temperature > minTemperature) {
        totals[zone] = (totals[zone] ?? 0) + (end - start);
      }
    } else if (type == 'group') {
      final children = node['children'] as List<Map<String, Object>>;
      final childTotals = calculateTotalHeatingTime(children, minTemperature);
      childTotals.forEach((zone, minutes) {
        totals[zone] = (totals[zone] ?? 0) + minutes;
      });
    }
  }
  return totals;
}

@pragma('vm:entry-point')
void main() {
  assert(calculateTotalHeatingTime([], 20).isEmpty);
  assert(calculateTotalHeatingTime([{'type': 'interval', 'zone': 'living', 'start': 0, 'end': 60, 'temperature': 25}], 20)['living'] == 60);
  assert(calculateTotalHeatingTime([{'type': 'group', 'children': [{'type': 'interval', 'zone': 'bedroom', 'start': 0, 'end': 30, 'temperature': 21}]}], 20)['bedroom'] == 30);
  print('All tests passed!');
}

