@pragma('vm:entry-point')
List<String> processBarcodeSequence(String digits) {
  final stack = <String>[];
  final output = <String>[];

  for (final ch in digits.split('')) {
    switch (ch) {
      case '1':
      case '2':
      case '3':
      case '4':
      case '5':
        stack.add('CAT$ch');
        break;
      case '6':
        if (stack.length >= 2) {
          final first = stack.removeLast();
          final second = stack.removeLast();
          stack.add('$second$first');
        }
        break;
      case '7':
        if (stack.isNotEmpty) {
          output.add(stack.removeLast());
        }
        break;
      case '8':
        if (stack.isNotEmpty) {
          stack.add(stack.last);
        }
        break;
      case '9':
        if (stack.isNotEmpty) {
          stack.removeLast();
        }
        break;
      case '0':
        stack.clear();
        break;
      default:
        break;
    }
  }

  while (stack.isNotEmpty) {
    output.add(stack.removeLast());
  }

  return output;
}

@pragma('vm:entry-point')
void main() {
  assert(processBarcodeSequence('').toString() == '[]');
  assert(processBarcodeSequence('3').toString() == '[CAT3]');
