  expect(candidate([['A1', 'A2', 'B1'], ['A3', 'A4', 'B2'], ['A5', 'A6', 'B3']]), {'A': 4, 'B': 3});
  expect(candidate([['A1', 'B1', 'A10'], ['B2', 'A2', 'B3'], ['A3', 'B4', 'A4']]), {'A': 1, 'B': 1});
