@pragma('vm:entry-point')
List<int> findDiscrepantEntries(List<int> ledger, int target) {
  List<int> _recurse(int left, int right) {
    if (left > right) return [];
    if (left == right) {
      return ledger[left] == target ? [left, left] : [];
    }
    int mid = (left + right) ~/ 2;
    List<int> leftAns = _recurse(left, mid);
    if (leftAns.isNotEmpty) return leftAns;
    List<int> rightAns = _recurse(mid + 1, right);
    if (rightAns.isNotEmpty) return rightAns;
    // crossing detection
    Map<int, int> leftSums = {};
    int s = 0;
    for (int i = mid; i >= left; i--) {
      s += ledger[i];
      leftSums[s] = i;
    }
    s = 0;
    for (int j = mid + 1; j <= right; j++) {
      s += ledger[j];
      int need = target - s;
      if (leftSums.containsKey(need)) {
        return [leftSums[need]!, j];
      }
    }
    return [];
  }
  return _recurse(0, ledger.length - 1);
}

@pragma('vm:entry-point')
void main() {
  assert(findDiscrepantEntries([10, -5, 3, -2, 7], 6).toString() == '[2, 4]');
  assert(findDiscrepantEntries([], 5).toString() == '[]');
  assert(findDiscrepantEntries([5], 5).toString() == '[0, 0]');
