List<String> simulateTrafficLightUndo(List<String> commands) {
  final stack = <String>[];
  final history = <String>[];
  for (final cmd in commands) {
    if (cmd == 'undo') {
      if (stack.isNotEmpty) stack.removeLast();
    } else {
      stack.add(cmd);
