List<int> selectLedgerEntriesByMinGap(List<int> entryDays, int minGap) {
  if (entryDays.isEmpty) return [];
  final selected = <int>[];
  var lastSelectedDay = entryDays[0] - minGap - 1;
  for (final day in entryDays) {
    if (day - lastSelectedDay >= minGap) {
      selected.add(day);
      lastSelectedDay = day;
    }
  }
  return selected;
}

