@pragma('vm:entry-point')
List<int> findQrScanlineRun(List<int> cumulativeWidths, int targetModule) {
  if (cumulativeWidths.isEmpty) return [-1, -1];
  int total = cumulativeWidths.last;
  if (targetModule < 0 || targetModule >= total) return [-1, -1];
  int left = 0;
  int right = cumulativeWidths.length - 1;
  while (left <= right) {
    int mid = (left + right) >> 1;
    if (cumulativeWidths[mid] <= targetModule) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  int prev = left > 0 ? cumulativeWidths[left - 1] : 0;
  return [left, cumulativeWidths[left] - prev];
}

@pragma('vm:entry-point')
void main() {
  assert(findQrScanlineRun([3, 5, 9, 10], 0).toString() == [0, 3].toString());
  assert(findQrScanlineRun([3, 5, 9, 10], 3).toString() == [1, 2].toString());
