Set<int> findValidHandSums(List<int> cards, int maxSum) {
  Set<int> results = {};
  void recurse(int index, int currentSum) {
    if (currentSum > maxSum) return;
    if (index == cards.length) {
      results.add(currentSum);
      return;
    }
    recurse(index + 1, currentSum);
    recurse(index + 1, currentSum + cards[index]);
  }
  recurse(0, 0);
  return results;
}

