double computeRowDispersion(int seatingMask) {
  // Edge case: no occupied seats yields zero dispersion
  if (seatingMask == 0) return 0.0;

  int mask = seatingMask;
  int totalOccupied = 0;
  int sumOfSquares = 0;

  // Process each contiguous block of occupied seats
  while (mask != 0) {
    // Step 1: Isolate the lowest set bit — start of a block
    int lowestBit = mask & (-mask);

    // Step 2: Walk upward from lowestBit to capture the full block
    int blockMask = 0;
    int probe = lowestBit;
    while ((mask & probe) != 0) {
      blockMask |= probe;
      probe <<= 1;
    }

    // Step 3: Count bits in the block (popcount via Kernighan's method)
    int len = 0;
    int temp = blockMask;
    while (temp != 0) {
      len++;
      temp &= temp - 1;
    }

    // Step 4: Accumulate statistics
    sumOfSquares += len * len;
    totalOccupied += len;

    // Step 5: Remove this block from the working mask
    mask ^= blockMask;
  }

  // Dispersion = sum(length^2) / total_occupied
  return sumOfSquares / totalOccupied;
}

