@pragma('vm:entry-point')
List<int> rankPasswords(List<String> passwords) {
  List<MapEntry<int, int>> entries = [];
  for (int i = 0; i < passwords.length; i++) {
    String p = passwords[i];
    int score = 0;
    if (p.length >= 8) score += 1;
    if (p.length >= 12) score += 1;
    bool hasUpper = false;
    bool hasLower = false;
    bool hasDigit = false;
    bool hasSpecial = false;
    for (int j = 0; j < p.length; j++) {
      int c = p.codeUnitAt(j);
      if (c >= 65 && c <= 90) hasUpper = true;
      if (c >= 97 && c <= 122) hasLower = true;
      if (c >= 48 && c <= 57) hasDigit = true;
      if ('!@#%^&*'.contains(p[j])) hasSpecial = true;
    }
    if (hasUpper) score += 1;
    if (hasLower) score += 1;
    if (hasDigit) score += 1;
    if (hasSpecial) score += 1;
    entries.add(MapEntry(i, score));
  }
  entries.sort((a, b) {
    if (a.value != b.value) return a.value.compareTo(b.value);
    return a.key.compareTo(b.key);
  });
  return entries.map((e) => e.key).toList();
}

