Set<int> findContinuousMixes(List<int> durations, int targetMinutes) {
  Set<int> result = {};
  int left = 0;
  int currentSum = 0;
  for (int right = 0; right < durations.length; right++) {
    currentSum += durations[right];
    while (currentSum > targetMinutes && left <= right) {
      currentSum -= durations[left];
      left++;
    }
    if (currentSum == targetMinutes) {
      result.add(left);
    }
  }
  return result;
}

