void main() {
  assert(maxBrightnessPath([[5]]) == 10);
  assert(maxBrightnessPath([[1, 2], [3, 4]]) == 12);
  assert(maxBrightnessPath([[1, 5, 1], [1, 5, 1], [1, 5, 1]]) == 22);
  print('All tests passed!');
}

