  assert(diceRoundTerritoryAnalysis([]).toString() == '[union:0]');
  assert(diceRoundTerritoryAnalysis([[[3, 4]]]).toString() == '[union:12]');
  assert(diceRoundTerritoryAnalysis([[[2, 2]], [[1, 1], [1, 1]]]).length == 2);
  print('All tests passed!');
}

