@pragma('vm:entry-point')
double averagePassengerWait(List<int> departures) {
  // A passenger arriving uniformly at any minute of the day (0..1439)
  // boards the next available train. Compute the expected wait in minutes.
  //
  // The day is treated as circular (24-hour cycle of 1440 minutes).
  // If the timetable is empty, no train ever arrives -> return 0.0.
  if (departures.isEmpty) {
    return 0.0;
  }

  // Normalize departures into [0, 1439] and drop duplicates.
  final Set<int> seen = <int>{};
  final List<int> unique = <int>[];
  for (final int t in departures) {
    final int norm = ((t % 1440) + 1440) % 1440;
    if (seen.add(norm)) {
      unique.add(norm);
    }
  }
  if (unique.isEmpty) {
    return 0.0;
  }

  // Sort chronologically so consecutive differences form the gaps.
  unique.sort();

  // Within a gap of size g, waiting times from its start are
  // 0, 1, 2, ..., g-1 whose sum equals g*(g-1)/2.
  double totalWait = 0.0;
  final int n = unique.length;
  for (int i = 0; i < n; i++) {
    final int current = unique[i];
    // The "next" train wraps around midnight back to the first service.
    final int nextTrain = (i + 1 < n) ? unique[i + 1] : unique[0] + 1440;
    final int gap = nextTrain - current;
    totalWait += (gap * (gap - 1)) / 2.0;
  }

  // Expected wait = average wait across every minute of the 1440-minute day.
  return totalWait / 1440.0;
}

