@pragma('vm:entry-point')
List<int> binPackManifest(List<int> weights, int capacity) {
  List<int> bins = [];
  int currentBin = 0;
  for (int w in weights) {
    if (currentBin + w > capacity) {
      if (currentBin > 0) {
        bins.add(currentBin);
      }
      currentBin = w;
    } else {
      currentBin += w;
    }
  }
  if (currentBin > 0) {
    bins.add(currentBin);
  }
  return bins;
}

