@pragma('vm:entry-point')
bool validateLedgerSequence(String tokens) {
  if (tokens.isEmpty) return false;
  if (tokens[0] != 'A') return false;
  if (tokens[tokens.length - 1] != 'Z') return false;

  int dCount = 0;
  int cCount = 0;

  for (int i = 0; i < tokens.length; i++) {
    String ch = tokens[i];
    String? next = (i < tokens.length - 1) ? tokens[i + 1] : null;

    if (ch == 'A') {
      if (next != 'D' && next != 'C') return false;
      dCount = 0;
      cCount = 0;
    } else if (ch == 'D') {
      if (next != 'D' && next != 'C' && next != 'R') return false;
      dCount++;
    } else if (ch == 'C') {
      if (next != 'D' && next != 'C' && next != 'R') return false;
      cCount++;
    } else if (ch == 'R') {
      if (dCount != cCount) return false;
      if (next != 'A' && next != 'Z') return false;
    } else if (ch == 'Z') {
      if (next != null) return false;
    } else {
      return false;
    }
  }

  return true;
}

