int countBalancedDnaWindows(String dna) {
  if (dna.length < 4) return 0;
  int count = 0;
  for (int i = 0; i <= dna.length - 4; i++) {
    Map<String, int> freq = {};
    for (int j = i; j < i + 4; j++) {
      String base = dna[j];
      freq[base] = (freq[base] ?? 0) + 1;
    }
    if (freq.length == 2) {
      bool balanced = true;
      for (int v in freq.values) {
        if (v != 2) {
          balanced = false;
          break;
        }
      }
      if (balanced) count++;
    }
  }
  return count;
}

