@pragma('vm:entry-point')
String warehouseZoneReport(List<List<int>> zones) {
  if (zones.isEmpty) return "union: 0, bounding: 0, efficiency: 0%";
  Set<int> xSet = {};
  Set<int> ySet = {};
  int minX = zones[0][0], maxX = zones[0][2];
  int minY = zones[0][1], maxY = zones[0][3];
  for (var z in zones) {
    xSet.add(z[0]);
    xSet.add(z[2]);
    ySet.add(z[1]);
    ySet.add(z[3]);
    if (z[0] < minX) minX = z[0];
    if (z[2] > maxX) maxX = z[2];
    if (z[1] < minY) minY = z[1];
    if (z[3] > maxY) maxY = z[3];
  }
  List<int> xs = xSet.toList()..sort();
  List<int> ys = ySet.toList()..sort();
  int unionArea = 0;
  for (int i = 0; i < xs.length - 1; i++) {
    for (int j = 0; j < ys.length - 1; j++) {
      bool covered = false;
      for (var z in zones) {
        if (z[0] <= xs[i] && xs[i] < z[2] && z[1] <= ys[j] && ys[j] < z[3]) {
          covered = true;
          break;
        }
      }
      if (covered) {
        unionArea += (xs[i + 1] - xs[i]) * (ys[j + 1] - ys[j]);
      }
    }
  }
  int boundingArea = (maxX - minX) * (maxY - minY);
  int eff = boundingArea == 0 ? 0 : (unionArea * 100 / boundingArea).round();
  return "union: $unionArea, bounding: $boundingArea, efficiency: $eff%";
}

@pragma('vm:entry-point')
void main() {
  assert(warehouseZoneReport([]) == "union: 0, bounding: 0, efficiency: 0%");
  assert(warehouseZoneReport([[0, 0, 3, 4]]) == "union: 12, bounding: 12, efficiency: 100%");
  assert(warehouseZoneReport([[0, 0, 2, 2], [1, 1, 3, 3]]) == "union: 7, bounding: 9, efficiency: 78%");
  print('All tests passed!');
}

