@pragma('vm:entry-point')
List<String> findMinimalWinningCoalitions(List<int> weights, int quota) {
  if (quota <= 0 || weights.isEmpty) return [];
  int totalWeight = 0;
  for (int w in weights) {
    totalWeight += w;
  }
  if (totalWeight < quota) return [];
  List<String> results = [];
  void backtrack(int idx, List<int> current, int currentSum) {
    if (currentSum >= quota) {
      bool minimal = true;
      for (int i = 0; i < current.length; i++) {
        if (currentSum - weights[current[i]] >= quota) {
          minimal = false;
          break;
        }
      }
      if (minimal) {
        results.add(current.join('+'));
      }
      return;
    }
    if (idx >= weights.length) return;
    int remaining = 0;
    for (int i = idx; i < weights.length; i++) {
      remaining += weights[i];
    }
    if (currentSum + remaining < quota) return;
    current.add(idx);
    backtrack(idx + 1, current, currentSum + weights[idx]);
    current.removeLast();
    backtrack(idx + 1, current, currentSum);
  }
  backtrack(0, [], 0);
  return results;
}

@pragma('vm:entry-point')
void main() {
  assert(findMinimalWinningCoalitions([3, 2, 1], 4).join(';') == '0+1;0+2');
  assert(findMinimalWinningCoalitions([5], 3).join(';') == '0');
  assert(findMinimalWinningCoalitions([1, 1, 1], 5).join(';') == '');
  print('All tests passed!');
}

tests:
