@pragma('vm:entry-point')
Map<String, int> summarizeElevatorDirections(List<int> requests, int currentFloor) {
  final upRequests = requests.where((r) => r > currentFloor).toList();
  final downRequests = requests.where((r) => r < currentFloor).toList();

  final maxDistance = requests.fold<int>(
    0,
    (max, r) {
      final dist = (r - currentFloor).abs();
      return dist > max ? dist : max;
    },
  );

  return {
    'up_total': upRequests.length,
    'up_unique': upRequests.toSet().length,
    'down_total': downRequests.length,
    'down_unique': downRequests.toSet().length,
    'max_distance': maxDistance,
  };
}

