@pragma('vm:entry-point')
String encodeLibraryShelfCode(String shelfCode) {
  if (shelfCode.isEmpty) return "EMPTY";

  int checksumTotal = 0;
  for (int i = 0; i < shelfCode.length; i++) {
    int c = shelfCode.codeUnitAt(i);
    bool isUpper = c >= 65 && c <= 90;
    bool isDigit = c >= 48 && c <= 57;
    if (!isUpper && !isDigit) {
      return "INVALID";
    }
    checksumTotal += c * (i + 1);
  }

  StringBuffer rle = StringBuffer();
  int count = 1;
  for (int i = 1; i <= shelfCode.length; i++) {
    if (i < shelfCode.length && shelfCode[i] == shelfCode[i - 1]) {
      count++;
    } else {
      while (count > 0) {
        int chunk = count > 9 ? 9 : count;
        rle.write('$chunk${shelfCode[i - 1]}');
        count -= chunk;
      }
      count = 1;
    }
  }

  int check = checksumTotal % 97;
  String checkStr = check.toString().padLeft(2, '0');
  return '${rle.toString()}-$checkStr';
}

