List<int> encodeMazePath(String path) {
  if (path.isEmpty) return [];
  List<int> res = [];
  int dirCode(String c) => c == 'U' ? 1 : c == 'R' ? 2 : c == 'D' ? 3 : 4;
  int curr = dirCode(path[0]), count = 1;
  for (int i = 1; i < path.length; i++) {
    int nxt = dirCode(path[i]);
    if (nxt == curr) count++;
    else { res.add(curr * 100 + count); curr = nxt; count = 1; }
  }
  res.add(curr * 100 + count);
  return res;
}

