List<int> getUnheatedBlockLengths(List<List<int>> activeIntervals, int totalDays, int buffer) {
  List<bool> heated = List.filled(totalDays, false);
  for (var interval in activeIntervals) {
    if (interval.length < 2) continue;
    int start = interval[0], end = interval[1];
    List<int> base = [];
    if (start <= end) {
      for (int i = start; i <= end; i++) base.add(i);
    } else {
      for (int i = start; i < totalDays; i++) base.add(i);
      for (int i = 0; i <= end; i++) base.add(i);
    }
    for (int h in base) {
      for (int offset = -buffer; offset <= buffer; offset++) {
        int day = (h + offset) % totalDays;
        if (day < 0) day += totalDays;
        heated[day] = true;
      }
    }
  }
  int firstHeated = -1;
  for (int i = 0; i < totalDays; i++) {
    if (heated[i]) { firstHeated = i; break; }
  }
  if (firstHeated == -1) return [totalDays];

  List<int> blocks = [];
  int currentLength = 0;
  for (int step = 0; step < totalDays; step++) {
    int day = ((firstHeated + 1 + step) % totalDays);
    if (!heated[day]) {
      currentLength++;
    } else if (currentLength > 0) {
      blocks.add(currentLength);
      currentLength = 0;
    }
  }
  if (currentLength > 0) blocks.add(currentLength);
  blocks.sort((a, b) => b.compareTo(a));
  return blocks;
}

