@pragma('vm:entry-point')
double calculateMaxSmoothWindowAverage(List<int> tallies, int windowSize, int maxDiff) {
  if (tallies.isEmpty || windowSize < 1 || tallies.length < windowSize) {
    return -1.0;
  }

  int currentSum = 0;
  int invalidCount = 0;

  for (int i = 0; i < windowSize; i++) {
    currentSum += tallies[i];
    if (i > 0 && (tallies[i] - tallies[i - 1]).abs() > maxDiff) {
      invalidCount++;
    }
  }

  double maxAvg = -1.0;
  if (invalidCount == 0) {
    maxAvg = currentSum / windowSize;
  }

  for (int i = windowSize; i < tallies.length; i++) {
    currentSum -= tallies[i - windowSize];
    currentSum += tallies[i];

    if (windowSize > 1) {
      if ((tallies[i - windowSize + 1] - tallies[i - windowSize]).abs() > maxDiff) {
        invalidCount--;
      }
      if ((tallies[i] - tallies[i - 1]).abs() > maxDiff) {
        invalidCount++;
      }
    }

    if (invalidCount == 0) {
      double currentAvg = currentSum / windowSize;
      if (currentAvg > maxAvg) {
        maxAvg = currentAvg;
      }
    }
  }

  return maxAvg;
