List<String> calculateSegmentCurrencyCosts(List<int> xCoords, List<int> yCoords) {
  List<String> costs = [];
  for (int i = 0; i < xCoords.length - 1; i++) {
    int area = (xCoords[i] - xCoords[i + 1]).abs() * (yCoords[i] - yCoords[i + 1]).abs();
    int cents = (area * 100 + 1) ~/ 3;
    costs.add('\$${(cents ~/ 100)}.${(cents % 100).toString().padLeft(2, '0')}');
  }
  return costs;
}

