@pragma('vm:entry-point')
/// Given a DNA string and integer k, groups each k-mer with its reverse
/// complement (A<->T, C<->G then reversed) into the same equivalence class.
/// The canonical representative is the lexicographically smaller of the
/// k-mer and its reverse complement. Returns the canonical representative
/// of the most frequent group. Ties broken by lexicographic order.
/// K-mers containing non-ATCG characters are skipped.
/// Returns "NONE" if no valid k-mers exist or parameters are invalid.
String mostFrequentComplementKmer(String dna, int k) {
  if (k <= 0 || dna.isEmpty || dna.length < k) return "NONE";
  final Map<String, String> comp = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C'};
  final Set<String> validBases = comp.keys.toSet();

  String reverseComplement(String s) {
    final StringBuffer sb = StringBuffer();
    for (int i = s.length - 1; i >= 0; i--) {
      if (!validBases.contains(s[i])) return '';
      sb.write(comp[s[i]]);
    }
    return sb.toString();
  }

  String canonical(String s) {
    final String rc = reverseComplement(s);
    if (rc.isEmpty) return '';
    return s.compareTo(rc) <= 0 ? s : rc;
  }

  final Map<String, int> freq = {};
  for (int i = 0; i <= dna.length - k; i++) {
    final String kmer = dna.substring(i, i + k);
    final String canon = canonical(kmer);
    if (canon.isEmpty) continue;
    freq[canon] = (freq[canon] ?? 0) + 1;
  }

  if (freq.isEmpty) return "NONE";
  final int maxFreq = freq.values.reduce((a, b) => a > b ? a : b);
  final List<String> top = freq.keys.where((key) => freq[key] == maxFreq).toList()..sort();
  return top.first;
}

@pragma('vm:entry-point')
void main() {
  assert(mostFrequentComplementKmer("ATCGAT", 2) == "AT");
  assert(mostFrequentComplementKmer("", 3) == "NONE");
  assert(mostFrequentComplementKmer("AAAA", 2) == "AA");
  print('All tests passed!');
}

tests:
