  final candidate = mostFrequentComplementKmer;

  expect(candidate("ATCGAT", 2), "AT");
  expect(candidate("", 3), "NONE");
  expect(candidate("AT", 5), "NONE");
  expect(candidate("ACGT", 0), "NONE");
  expect(candidate("A", 1), "A");
  expect(candidate("ATXG", 2), "AT");
  expect(candidate("XXXX", 2), "NONE");
  expect(candidate("AACGTT", 2), "AA");
  expect(candidate("ACGTACGT", 3), "ACG");
