Map<String, int> longestBalancedPlaylistSegment(List<int> playlist, int repeatLimit) {
  if (playlist.isEmpty) return {"start": -1, "end": -1, "length": 0};

  Map<int, int> count = {};
  int left = 0;
  int bestStart = 0, bestEnd = -1, bestLen = 0;

  for (int right = 0; right < playlist.length; right++) {
    int song = playlist[right];
    count[song] = (count[song] ?? 0) + 1;

    while (count[song]! > repeatLimit) {
      int leftSong = playlist[left];
      count[leftSong] = count[leftSong]! - 1;
      if (count[leftSong] == 0) count.remove(leftSong);
      left++;
    }

    if (left <= right) {
      int currentLen = right - left + 1;
      if (currentLen > bestLen) {
        bestLen = currentLen;
        bestStart = left;
        bestEnd = right;
      }
    }
  }

  return {"start": bestStart, "end": bestEnd, "length": bestLen};
}

@pragma('vm:entry-point')
void main() {
  assert(longestBalancedPlaylistSegment([1, 2, 1, 1, 3], 2).toString() == "{start: 1, end: 4, length: 4}");
  assert(longestBalancedPlaylistSegment([5, 5, 5, 5], 2).toString() == "{start: 0, end: 1, length: 2}");
  assert(longestBalancedPlaylistSegment([], 3).toString() == "{start: -1, end: -1, length: 0}");
