bool canPairCentRemainders(List<double> remainders) {
  if (remainders.length % 2 != 0) return false;
  if (remainders.isEmpty) return true;
  double first = remainders[0];
  for (int i = 1; i < remainders.length; i++) {
    if (first + remainders[i] == 1.0) {
      List<double> rest = [];
      for (int j = 0; j < remainders.length; j++) {
        if (j != 0 && j != i) rest.add(remainders[j]);
      }
      if (canPairCentRemainders(rest)) return true;
    }
  }
  return false;
}

