@pragma('vm:entry-point')
Map<String, int> findKthDriestMoisture(List<List<int>> moistureGrid, int k) {
  if (moistureGrid.isEmpty || k <= 0) return {'moistureLevel': -1, 'cellsAtOrBelow': 0};
  int rows = moistureGrid.length;
  int cols = moistureGrid[0].length;
  int low = moistureGrid[0][0];
  int high = moistureGrid[0][cols - 1];
  for (int r = 0; r < rows; r++) {
    if (moistureGrid[r][0] < low) low = moistureGrid[r][0];
    if (moistureGrid[r][cols - 1] > high) high = moistureGrid[r][cols - 1];
  }
  while (low < high) {
    int mid = low + (high - low) ~/ 2;
    int count = 0;
    for (int r = 0; r < rows; r++) {
      List<int> row = moistureGrid[r];
      int left = 0, right = cols;
      while (left < right) {
        int m = left + (right - left) ~/ 2;
        if (row[m] <= mid) {
          left = m + 1;
        } else {
          right = m;
        }
      }
      count += left;
    }
    if (count < k) {
      low = mid + 1;
    } else {
      high = mid;
    }
  }
  int finalCount = 0;
  for (int r = 0; r < rows; r++) {
    List<int> row = moistureGrid[r];
    int left = 0, right = cols;
    while (left < right) {
      int m = left + (right - left) ~/ 2;
      if (row[m] <= low) {
        left = m + 1;
      } else {
        right = m;
      }
    }
    finalCount += left;
  }
  return {'moistureLevel': low, 'cellsAtOrBelow': finalCount};
}

