Map<String, int> tallyQrModuleRuns(List<int> row) {
  int n = row.length;
  if (n == 0) return {'total':0,'black':0,'white':0,'blackRuns':0,'whiteRuns':0};
  int black = 0, bRuns=0, wRuns=0;
  bool prev = row[0]==1;
  if (prev) bRuns++; else wRuns++;
  for (int v in row) { if (v==1) black++; }
  for (int i=1; i<n; i++) {
    bool cur = row[i]==1;
    if (cur != prev) { if (cur) bRuns++; else wRuns++; prev=cur; }
  }
  return {'total':n,'black':black,'white':n-black,'blackRuns':bRuns,'whiteRuns':wRuns};
}

