@pragma('vm:entry-point')
String renderQrModuleRuns(List<int> runLengths) {
  if (runLengths.isEmpty) return '';
  var cleaned = runLengths.where((l) => l > 0).toList();
  var deduped = cleaned.fold<List<int>>([], (prev, curr) {
    if (prev.isNotEmpty && prev.last == curr) {
      prev[prev.length - 1] += curr;
    } else {
      prev.add(curr);
    }
    return prev;
  });
  var groups = <List<int>>[];
  var current = <int>[];
  for (var len in deduped) {
    current.add(len);
    if (current.length == 5) {
      groups.add(current);
      current = <int>[];
    }
  }
  if (current.isNotEmpty) groups.add(current);
  var mapped = groups.map((g) {
    return g.asMap().entries.map((e) {
      var ch = (e.key % 2 == 0) ? '█' : ' ';
      return List.filled(e.value, ch).join();
    }).join();
  }).toList();
  var folded = mapped.fold<String>('', (a, b) => a + b + '|');
  return folded.substring(0, folded.length - 1);
}

@pragma('vm:entry-point')
void main() {
  assert(renderQrModuleRuns([1,1,3,1,1]) == '█ ███ █');
  assert(renderQrModuleRuns([]) == '');
