@pragma('vm:entry-point')
List<int> parseThermostatWeeklySetpoints(String schedule) {
  List<int> result = List<int>.filled(168, -1);
  if (schedule.isEmpty) return result;
  List<String> rules = schedule.split(';');
  for (String rule in rules) {
    rule = rule.trim();
    if (rule.isEmpty) continue;
    List<String> parts = rule.split(':');
    if (parts.length != 2) continue;
    String timeRange = parts[0].trim();
    String tempStr = parts[1].trim();
    int temp = int.tryParse(tempStr) ?? -1;
    if (temp < 10 || temp > 30) continue;
    List<String> daysAndHours = timeRange.split(' ');
    if (daysAndHours.length != 2) continue;
    String daysPart = daysAndHours[0];
    String hourPart = daysAndHours[1];
    List<String> hourTokens = hourPart.split('-');
    if (hourTokens.length != 2) continue;
    int startHour = int.tryParse(hourTokens[0]) ?? -1;
    int endHour = int.tryParse(hourTokens[1]) ?? -1;
    if (startHour < 0 || endHour > 23 || startHour > endHour) continue;
    Set<int> activeDays = {};
    for (int i = 0; i < daysPart.length; i++) {
      String ch = daysPart[i];
      if (ch == 'M') activeDays.add(0);
      else if (ch == 'T') activeDays.add(1);
      else if (ch == 'W') activeDays.add(2);
      else if (ch == 'R') activeDays.add(3);
      else if (ch == 'F') activeDays.add(4);
      else if (ch == 'S') activeDays.add(5);
      else if (ch == 'U') activeDays.add(6);
    }
    for (int d in activeDays) {
      for (int h = startHour; h <= endHour; h++) {
        result[d * 24 + h] = temp;
      }
    }
  }
  return result;
}

