int calculateSatellitePassWindows(List<int> visibility) {
  if (visibility.isEmpty) return 0;
  int count = 0;
  int state = 0;
  for (int i = 0; i < visibility.length; i++) {
    int v = visibility[i];
    if (state == 0) {
      if (v == 1) {
        state = 1;
      }
    } else {
