@pragma('vm:entry-point')
double computeAverageRequestFulfillmentTime(List<int> floors, int initialFloor) {
  if (floors.isEmpty) return 0.0;
  List<double> totals = [];
  void backtrack(List<int> remaining, List<int> path) {
    if (remaining.isEmpty) {
      double time = 0.0;
      int pos = initialFloor;
      for (int f in path) {
        time += (pos - f).abs() * 0.5;
        pos = f;
      }
      totals.add(time);
      return;
    }
    for (int i = 0; i < remaining.length; i++) {
      int next = remaining[i];
      path.add(next);
      backtrack(
          remaining.sublist(0, i) + remaining.sublist(i + 1), path);
      path.removeLast();
    }
  }
  backtrack(floors, []);
  double sum = 0.0;
  for (double t in totals) {
    sum += t;
  }
  return sum / totals.length;
}

@pragma('vm:entry-point')
void main() {
  assert(computeAverageRequestFulfillmentTime([], 0) == 0.0);
  assert(computeAverageRequestFulfillmentTime([3], 0) == 1.5);
