@pragma('vm:entry-point')
List<int> kthClosestKingSquare(int n, int kr, int kc, int k) {
  // A king stands on square (kr, kc) of an n x n board (1-indexed).
  // The distance to any square is the number of king moves (Chebyshev).
  // Find the distance d of the k-th closest square (ties share a distance),
  // and return [d, squares within distance d, squares at exactly distance d].
  int countWithin(int d) {
    if (d < 0) return 0;
    int rLo = kr - d < 1 ? 1 : kr - d;
    int rHi = kr + d > n ? n : kr + d;
    int cLo = kc - d < 1 ? 1 : kc - d;
    int cHi = kc + d > n ? n : kc + d;
    return (rHi - rLo + 1) * (cHi - cLo + 1);
  }

  int maxR = kr - 1 > n - kr ? kr - 1 : n - kr;
  int maxC = kc - 1 > n - kc ? kc - 1 : n - kc;
  int lo = 0;
  int hi = maxR > maxC ? maxR : maxC;
  while (lo < hi) {
    int mid = lo + (hi - lo) ~/ 2;
    if (countWithin(mid) >= k) {
      hi = mid;
    } else {
      lo = mid + 1;
    }
  }
  int within = countWithin(lo);
  int exact = within - countWithin(lo - 1);
  return [lo, within, exact];
}

@pragma('vm:entry-point')
void main() {
  assert(kthClosestKingSquare(8, 4, 4, 1).toString() == '[0, 1, 1]');
  assert(kthClosestKingSquare(8, 1, 1, 10)[0] == 3);
  assert(kthClosestKingSquare(5, 3, 3, 25).toString() == '[2, 25, 16]');
  print('All tests passed!');
}

