@pragma('vm:entry-point')
List<int> longestGreenStretch(List<int> phases) {
  // phases: 0 = red, 1 = yellow, 2 = green (one entry per second)
  // Returns [startIndex, length] of the longest unbroken green stretch.
  // If there is no green phase, returns [-1, 0]. Ties keep the earliest start.
  int bestStart = -1;
  int bestLen = 0;
  int windowStart = 0;
  for (int i = 0; i < phases.length; i++) {
    if (phases[i] != 2) {
      windowStart = i + 1;
      continue;
    }
    int len = i - windowStart + 1;
    if (len > bestLen) {
      bestLen = len;
      bestStart = windowStart;
    }
  }
  return [bestStart, bestLen];
}

