int maxEnjoymentWithSkipLimit(List<int> ratings, int maxSkip) {
  // A playlist plays songs in order. You may skip songs, but you can never
  // skip more than maxSkip songs in a row (including before the first song
  // you listen to and after the last one). Each listened song adds its
  // rating (possibly negative) to your enjoyment. Return the maximum total
  // enjoyment achievable. If the whole playlist can be skipped (its length
  // is at most maxSkip), the answer is at least 0.
  final int n = ratings.length;
  if (n == 0) return 0;
  const int negInf = -1000000000;
  final List<int> dp = List<int>.filled(n, negInf);
  for (int i = 0; i < n; i++) {
    int best = negInf;
    // Can song i be the first listened song? Only if at most maxSkip
    // songs precede it.
    if (i <= maxSkip) best = 0;
    // Otherwise the previous listened song j must satisfy i - j - 1 <= maxSkip.
    int lo = i - maxSkip - 1;
    if (lo < 0) lo = 0;
    for (int j = lo; j < i; j++) {
      if (dp[j] > best) best = dp[j];
    }
    if (best > negInf) dp[i] = ratings[i] + best;
  }
  int answer = negInf;
  // Skipping the entire playlist is allowed only if n <= maxSkip.
  if (n <= maxSkip) answer = 0;
  // The last listened song must leave at most maxSkip songs after it.
  int lo = n - 1 - maxSkip;
  if (lo < 0) lo = 0;
  for (int i = lo; i < n; i++) {
    if (dp[i] > answer) answer = dp[i];
  }
  return answer;
}

