@pragma('vm:entry-point')
double rgbChannelMedian(List<int> red, List<int> green, List<int> blue) {
  int countLessOrEqual(List<int> values, int target) {
    int low = 0;
    int high = values.length;

    while (low < high) {
      int mid = (low + high) ~/ 2;
      if (values[mid] <= target) {
        low = mid + 1;
      } else {
        high = mid;
      }
    }

    return low;
  }

  int kthSmallest(int k) {
    int low = 0;
    int high = 255;

    while (low < high) {
      int mid = (low + high) ~/ 2;
      int count = countLessOrEqual(red, mid) +
          countLessOrEqual(green, mid) +
          countLessOrEqual(blue, mid);

      if (count <= k) {
        low = mid + 1;
      } else {
        high = mid;
      }
    }

    return low;
  }

  int total = red.length + green.length + blue.length;

  if (total == 0) {
    return -1.0;
  }

  if (total % 2 == 1) {
    return kthSmallest(total ~/ 2).toDouble();
  }

  int left = kthSmallest((total ~/ 2) - 1);
  int right = kthSmallest(total ~/ 2);
  return (left + right) / 2.0;
}

