@pragma('vm:entry-point')
Map<String, int> analyzeHashBucketSearches(List<int> bucketCounts, List<int> targets) {
  List<int> sorted = List<int>.from(bucketCounts);
  sorted.sort();

  int lowerBound(int value) {
    int left = 0;
    int right = sorted.length;

    while (left < right) {
      int mid = left + ((right - left) ~/ 2);
      if (sorted[mid] < value) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }

    return left;
  }

  int upperBound(int value) {
    int left = 0;
    int right = sorted.length;

    while (left < right) {
      int mid = left + ((right - left) ~/ 2);
      if (sorted[mid] <= value) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }

    return left;
  }

  int exactMatches = 0;
  int smallerBuckets = 0;
  int largerBuckets = 0;

  for (int target in targets) {
    int lower = lowerBound(target);
    int upper = upperBound(target);

    if (upper > lower) {
      exactMatches++;
    }

    smallerBuckets += lower;
    largerBuckets += sorted.length - upper;
  }

  return {
    'exactMatches': exactMatches,
    'smallerBuckets': smallerBuckets,
    'largerBuckets': largerBuckets,
  };
}

@pragma('vm:entry-point')
void main() {
  assert(analyzeHashBucketSearches([1, 3, 3, 7], [3]).toString() == '{exactMatches: 1, smallerBuckets: 1, largerBuckets: 1}');
  assert(analyzeHashBucketSearches([], [2, 5])['largerBuckets'] == 0);
  assert(analyzeHashBucketSearches([2, 4, 6], [1, 7])['smallerBuckets'] == 3);
  print('All tests passed!');
}

