int countCertifiedVotes(String tape) {
  int votes = 0;
  bool certified = false;

  for (int i = 0; i < tape.length; i++) {
    String ch = tape[i];
    if (ch == '[') {
      certified = true;
    } else if (ch == ']') {
      certified = false;
    } else if (certified && (ch == 'A' || ch == 'B')) {
      votes++;
    }
  }

  return votes;
}

