String decodeScaledIngredientTape(String tape, int scale) {
  final StringBuffer output = StringBuffer();
  int i = 0;

  while (i < tape.length) {
    int count = 0;

    while (i < tape.length) {
      int digit = tape.codeUnitAt(i) - 48;
      if (digit < 0 || digit > 9) {
        break;
      }
      count = (count * 10) + digit;
      i++;
    }

    if (count == 0) {
      count = 1;
    }

    if (i >= tape.length) {
      break;
    }

    String command = tape[i++];

    if (command == '*') {
      if (i >= tape.length) {
        break;
      }
      String ch = tape[i++];
      int repeats = count * scale;
      for (int r = 0; r < repeats; r++) {
        output.write(ch);
      }
    } else if (command == '+') {
      if (i >= tape.length) {
        break;
      }
      String ch = tape[i++];
      int code = ch.codeUnitAt(0);

      if (code >= 97 && code <= 122) {
        int shift = (count + scale) % 26;
        int decoded = ((code - 97 - shift) % 26 + 26) % 26;
        output.writeCharCode(decoded + 97);
      } else {
        output.write(ch);
      }
    } else if (command == '?') {
      int sum = 0;
      String current = output.toString();
      for (int j = 0; j < current.length; j++) {
        sum += current.codeUnitAt(j);
      }
      int value = (sum + count + scale) % 26;
      output.writeCharCode(97 + value);
    } else {
      for (int r = 0; r < count; r++) {
        output.write(command);
      }
    }
  }

  return output.toString();
}

