  assert(decodeScaledIngredientTape("3*a2+b?", 2) == "aaaaaaxd");
  assert(decodeScaledIngredientTape("2+f1*Z", 1) == "cZ");
  assert(decodeScaledIngredientTape("", 3) == "");
  print('All tests passed!');
}

