  assert(soilMoistureRowTotals("DM,W").toString() == "[6]");
  assert(soilMoistureRowTotals("2:[DW]").toString() == "[10]");
  assert(soilMoistureRowTotals("D,[MW,D];3:M").toString() == "[12, 6]");
  print('All tests passed!');
