@pragma('vm:entry-point')
List<String> orderRgbPixelsByDominance(List<String> pixels) {
  Map<String, int> categoryCounts = {
    'R': 0,
    'G': 0,
    'B': 0,
    'X': 0,
  };

  String categoryOf(List<int> rgb) {
    int r = rgb[0];
    int g = rgb[1];
    int b = rgb[2];

    if (r > g && r > b) {
      return 'R';
    }
    if (g > r && g > b) {
      return 'G';
    }
    if (b > r && b > g) {
      return 'B';
    }
    return 'X';
  }

  List<Map<String, Object>> parsed = [];

  for (String pixel in pixels) {
    List<String> parts = pixel.split(',');
    List<int> rgb = [
      int.parse(parts[0]),
      int.parse(parts[1]),
      int.parse(parts[2]),
    ];

    String category = categoryOf(rgb);
    categoryCounts[category] = categoryCounts[category]! + 1;

    parsed.add({
      'text': pixel,
      'rgb': rgb,
      'category': category,
    });
  }

  Map<String, int> categoryRank = {
    'R': 0,
    'G': 1,
    'B': 2,
    'X': 3,
  };

  parsed.sort((a, b) {
    String ca = a['category'] as String;
    String cb = b['category'] as String;

    bool ax = ca == 'X';
    bool bx = cb == 'X';

    if (ax != bx) {
      return ax ? 1 : -1;
    }

    int rarityCompare = categoryCounts[ca]!.compareTo(categoryCounts[cb]!);
    if (rarityCompare != 0) {
      return rarityCompare;
    }

    int rankCompare = categoryRank[ca]!.compareTo(categoryRank[cb]!);
    if (rankCompare != 0) {
      return rankCompare;
    }

    List<int> ra = a['rgb'] as List<int>;
    List<int> rb = b['rgb'] as List<int>;

    int spreadA = [ra[0], ra[1], ra[2]].reduce((x, y) => x > y ? x : y) -
        [ra[0], ra[1], ra[2]].reduce((x, y) => x < y ? x : y);
    int spreadB = [rb[0], rb[1], rb[2]].reduce((x, y) => x > y ? x : y) -
        [rb[0], rb[1], rb[2]].reduce((x, y) => x < y ? x : y);

    if (spreadA != spreadB) {
      return spreadB.compareTo(spreadA);
    }

    int weightA = ra[0] * 3 + ra[1] * 4 + ra[2] * 2;
    int weightB = rb[0] * 3 + rb[1] * 4 + rb[2] * 2;

    if (weightA != weightB) {
      return weightA.compareTo(weightB);
    }

    return (a['text'] as String).compareTo(b['text'] as String);
  });

  return parsed.map((e) => e['text'] as String).toList();
}

@pragma('vm:entry-point')
void main() {
  assert(orderRgbPixelsByDominance([]).toString() == [].toString());
  assert(orderRgbPixelsByDominance(['255,0,0','0,255,0','0,0,255','9,9,9']).toString() == ['255,0,0','0,255,0','0,0,255','9,9,9'].toString());
  assert(orderRgbPixelsByDominance(['9,1,1','8,0,0','7,3,3']).toString() == ['8,0,0','9,1,1','7,3,3'].toString());
  print('All tests passed!');
}

