@pragma('vm:entry-point')
String spiralMorseDecoder(List<String> grid) {
  if (grid.isEmpty) {
    return '';
  }

  const morse = {
    '.': 'E',
    '-': 'T',
    '..': 'I',
    '--': 'M',
    '.-': 'A',
    '-.': 'N',
    '...': 'S',
    '---': 'O',
    '....': 'H'
  };

  int cols = 0;
  for (final row in grid) {
    if (row.length > cols) {
      cols = row.length;
    }
  }

  final out = StringBuffer();
  final current = StringBuffer();

  void processCell(int r, int c) {
    if (c >= grid[r].length) {
      return;
    }

    final ch = grid[r][c];
    if (ch == '.' || ch == '-') {
      current.write(ch);
    } else if (ch == '/' || ch == '|') {
      if (current.isNotEmpty) {
        out.write(morse[current.toString()] ?? '?');
        current.clear();
      }
      if (ch == '|' && out.isNotEmpty && !out.toString().endsWith(' ')) {
        out.write(' ');
      }
    }
  }

  int top = 0;
  int bottom = grid.length - 1;
  int left = 0;
  int right = cols - 1;

  while (top <= bottom && left <= right) {
    for (int c = left; c <= right; c++) {
      processCell(top, c);
    }
    top++;

    for (int r = top; r <= bottom; r++) {
      processCell(r, right);
    }
    right--;

    if (top <= bottom) {
      for (int c = right; c >= left; c--) {
        processCell(bottom, c);
      }
      bottom--;
    }

    if (left <= right) {
      for (int r = bottom; r >= top; r--) {
        processCell(r, left);
      }
      left++;
    }
  }

  if (current.isNotEmpty) {
    out.write(morse[current.toString()] ?? '?');
  }

  return out.toString().trimRight();
}

@pragma('vm:entry-point')
void main() {
  assert(spiralMorseDecoder([]) == '');
  assert(spiralMorseDecoder(['./-/']) == 'ET');
  assert(spiralMorseDecoder(['.|-/']) == 'E T');
  print('All tests passed!');
}

