@pragma('vm:entry-point')
int countMatchingSuitRows(List<List<String>> deckRows) {
  int matchingRows = 0;

  for (List<String> row in deckRows) {
    if (row.isEmpty) {
      continue;
    }

    String suit = row[0].substring(row[0].length - 1);
    bool allMatch = true;

    for (String card in row) {
      if (card.substring(card.length - 1) != suit) {
        allMatch = false;
        break;
      }
    }

    if (allMatch) {
      matchingRows++;
    }
  }

  return matchingRows;
}

@pragma('vm:entry-point')
void main() {
  assert(countMatchingSuitRows([["AH", "7H"], ["KC", "QC"]]) == 2);
  assert(countMatchingSuitRows([["AS", "KD"], ["2C", "5C"]]) == 1);
  assert(countMatchingSuitRows([]) == 0);
  print('All tests passed!');
}

tests:
